//! 🧳️ Configuration decode and dispatch preserve whole original native, receiving and Store causes.
use semio_framework_job::{OriginalDomainFailure, OriginalDomainProjection, OriginalDomainView as V, OriginalTurnFailure, project_original_turn_failure, key_original_turn_failure, project_original_value_error, key_original_value_error};
use semio_framework_value::{ValueError, ValueRefusalKind, RetainedCloneProgress, Number};
use store::os_vcs::VcsError;

#[doc(hidden)]
#[derive(Debug,semio_framework_value::RetireOwned)]
pub enum OriginalConfigurationFailure{Original(OriginalTurnFailure),Admission(semio_framework::ToolDispatchError),Native{producer:ValueError,receiving:OriginalTurnFailure},Store(VcsError)}
impl OriginalDomainFailure for OriginalConfigurationFailure{
 fn domain_code(&self)->&str{"configuration.original"}
 fn domain_message(&self)->&str{match self{Self::Original(_)=>"configuration original worker failed",Self::Admission(source)=>match source{semio_framework::ToolDispatchError::UnknownController{controller_id}=>controller_id,semio_framework::ToolDispatchError::Factory{detail,..}=>detail,semio_framework::ToolDispatchError::RawWireLimit{..}=>"configuration wire exceeds its declared original input ceiling"},Self::Native{producer,..}=>&producer.message,Self::Store(source)=>store_message(source)}}
 fn domain_retained_progress(&self)->RetainedCloneProgress{Default::default()}
}
#[doc(hidden)]
pub fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original configuration failure projection path changed")}
#[doc(hidden)]
pub fn text_list<'a>(list:&'a[String],path:&[usize])->Result<V<'a>,ValueError>{match path{[]=>Ok(V::IntrinsicArray(list.len())),[index]=>list.get(*index).map(|text|V::IntrinsicText(text)).ok_or_else(invalid),_=>Err(invalid())}}
#[doc(hidden)]
pub fn number(value:usize)->V<'static>{V::IntrinsicNumber(Number::UInt(value as u64))}
fn store_kind(source:&VcsError)->&'static str{match source{
 VcsError::UnknownEdit(_)=>"unknownEdit",VcsError::UnknownChange(_)=>"unknownChange",VcsError::UnknownAlternative(_)=>"unknownAlternative",VcsError::NoCheckpoint=>"noCheckpoint",VcsError::EmptyApply=>"emptyApply",VcsError::MutationApply(_)=>"mutationApply",VcsError::InverseRefused(_)=>"inverseRefused",VcsError::NativeEncoding(_)=>"nativeEncoding",VcsError::NothingToUndo=>"nothingToUndo",VcsError::ForeignEdit(_)=>"foreignEdit",VcsError::NothingToRedo=>"nothingToRedo",VcsError::Serialize(_)=>"serialize",VcsError::Deserialize(_)=>"deserialize",VcsError::Backbone(_)=>"backbone",VcsError::DialectMismatch(_)=>"dialectMismatch",VcsError::MigrationRequired(_)=>"migrationRequired",VcsError::MigrationFailed(_)=>"migrationFailed",VcsError::CompositionCycle(_)=>"compositionCycle",VcsError::OwnershipViolation(_)=>"ownershipViolation",VcsError::ValidationFailed(_)=>"validationFailed",VcsError::CompensationFailed(_)=>"compensationFailed",VcsError::Rejected{..}=>"rejected",VcsError::UnknownConflict(_)=>"unknownConflict",VcsError::Stale{..}=>"stale",VcsError::HistoryShape{..}=>"historyShape",VcsError::TransactionOpen{..}=>"transactionOpen",VcsError::UnknownTransaction(_)=>"unknownTransaction",VcsError::HistoryFull{..}=>"historyFull",VcsError::HistoryReplaying=>"historyReplaying",VcsError::TooLarge{..}=>"tooLarge",VcsError::UnitSpansDocuments{..}=>"unitSpansDocuments"}}
fn store_message(source:&VcsError)->&str{match source{
 VcsError::UnknownEdit(text)|VcsError::UnknownChange(text)|VcsError::UnknownAlternative(text)|VcsError::ForeignEdit(text)|VcsError::Serialize(text)|VcsError::Deserialize(text)|VcsError::Backbone(text)|VcsError::DialectMismatch(text)|VcsError::MigrationRequired(text)|VcsError::MigrationFailed(text)|VcsError::CompositionCycle(text)|VcsError::OwnershipViolation(text)|VcsError::ValidationFailed(text)|VcsError::CompensationFailed(text)|VcsError::UnknownConflict(text)|VcsError::UnknownTransaction(text)=>text,
 VcsError::TransactionOpen{transaction_id}=>transaction_id,VcsError::UnitSpansDocuments{mutation_id,..}=>mutation_id,VcsError::MutationApply(error)=>&error.message,VcsError::InverseRefused(error)|VcsError::NativeEncoding(error)=>&error.message,_=>store_kind(source)}}
#[doc(hidden)]
pub fn message<'a>(source:&'a protocol::MutationMessage,path:&[usize])->Result<V<'a>,ValueError>{Ok(match path{[]=>V::IntrinsicObject(5),[0]=>number(source.level.as_u8()as usize),[1]=>V::IntrinsicText(&source.code.0),[2]=>V::IntrinsicText(&source.message),[3,rest @ ..]=>return text_list(&source.target,rest),[4]=>source.op_index.map_or(V::IntrinsicNull,|index|number(index as usize)),_=>return Err(invalid())})}
fn message_key<'a>(_:&'a protocol::MutationMessage,path:&[usize],index:usize)->Result<&'a str,ValueError>{match path{[]=>["level","code","message","target","opIndex"].get(index).copied().ok_or_else(invalid),_=>Err(invalid())}}
fn store_value<'a>(source:&'a VcsError,path:&[usize])->Result<V<'a>,ValueError>{Ok(match source{
 VcsError::UnknownEdit(text)|VcsError::UnknownChange(text)|VcsError::UnknownAlternative(text)|VcsError::ForeignEdit(text)|VcsError::Serialize(text)|VcsError::Deserialize(text)|VcsError::Backbone(text)|VcsError::DialectMismatch(text)|VcsError::MigrationRequired(text)|VcsError::MigrationFailed(text)|VcsError::CompositionCycle(text)|VcsError::OwnershipViolation(text)|VcsError::ValidationFailed(text)|VcsError::CompensationFailed(text)|VcsError::UnknownConflict(text)|VcsError::UnknownTransaction(text)=>match path{[]=>V::IntrinsicText(text),_=>return Err(invalid())},
 VcsError::InverseRefused(error)|VcsError::NativeEncoding(error)=>return project_original_value_error(error,path),
 VcsError::MutationApply(error)=>match path{[]=>V::IntrinsicObject(3),[0]=>V::IntrinsicText(&error.code),[1]=>V::IntrinsicText(&error.message),[2,rest @ ..]=>return text_list(&error.target,rest),_=>return Err(invalid())},
 VcsError::Rejected{policy,messages}=>match path{[]=>V::IntrinsicObject(2),[0]=>number(policy.as_u8()as usize),[1]=>V::IntrinsicArray(messages.len()),[1,index,rest @ ..]=>return message(messages.get(*index).ok_or_else(invalid)?,rest),_=>return Err(invalid())},
 VcsError::Stale{expected_generation,generation}=>match path{[]=>V::IntrinsicObject(2),[0]=>V::IntrinsicNumber(Number::UInt(*expected_generation)),[1]=>V::IntrinsicNumber(Number::UInt(*generation)),_=>return Err(invalid())},
 VcsError::HistoryShape{shape,kind}=>match path{[]=>V::IntrinsicObject(2),[0]=>V::IntrinsicText(shape.name()),[1]=>V::IntrinsicText(kind.name()),_=>return Err(invalid())},
 VcsError::TransactionOpen{transaction_id}=>match path{[]=>V::IntrinsicText(transaction_id),_=>return Err(invalid())},
 VcsError::HistoryFull{capacity}=>match path{[]=>number(*capacity),_=>return Err(invalid())},
 VcsError::TooLarge{rows,capacity}=>match path{[]=>V::IntrinsicObject(2),[0]=>number(*rows),[1]=>number(*capacity),_=>return Err(invalid())},
 VcsError::UnitSpansDocuments{mutation_id,unit}=>match path{[]=>V::IntrinsicObject(2),[0]=>V::IntrinsicText(mutation_id),[1]=>V::IntrinsicText(unit),_=>return Err(invalid())},
 VcsError::NoCheckpoint|VcsError::EmptyApply|VcsError::NothingToUndo|VcsError::NothingToRedo|VcsError::HistoryReplaying=>match path{[]=>V::IntrinsicNull,_=>return Err(invalid())},
 })}
fn store_key<'a>(source:&'a VcsError,path:&[usize],index:usize)->Result<&'a str,ValueError>{let keys:&[&str]=match source{
 VcsError::InverseRefused(error)|VcsError::NativeEncoding(error)=>return key_original_value_error(error,path,index),
 VcsError::MutationApply(_)=>&["code","message","target"],VcsError::Rejected{messages,..}=>match path{[]=>&["policy","messages"],[1,at,rest @ ..]=>return message_key(messages.get(*at).ok_or_else(invalid)?,rest,index),_=>return Err(invalid())},VcsError::Stale{..}=>&["expectedGeneration","generation"],VcsError::HistoryShape{..}=>&["shape","kind"],VcsError::TooLarge{..}=>&["rows","capacity"],VcsError::UnitSpansDocuments{..}=>&["mutationId","unit"],_=>return Err(invalid())};if path.is_empty(){keys.get(index).copied().ok_or_else(invalid)}else{Err(invalid())}}
#[doc(hidden)]
pub fn admission<'a>(source:&'a semio_framework::ToolDispatchError,path:&[usize])->Result<V<'a>,ValueError>{Ok(match path{[]=>V::IntrinsicObject(6),[0]=>V::IntrinsicText(match source{semio_framework::ToolDispatchError::UnknownController{..}=>"unknownController",semio_framework::ToolDispatchError::Factory{..}=>"factory",semio_framework::ToolDispatchError::RawWireLimit{..}=>"rawWireLimit"}),[1]=>V::IntrinsicText(match source{semio_framework::ToolDispatchError::UnknownController{controller_id}|semio_framework::ToolDispatchError::Factory{controller_id,..}|semio_framework::ToolDispatchError::RawWireLimit{controller_id,..}=>controller_id}),[2]=>match source{semio_framework::ToolDispatchError::Factory{tool_id,..}|semio_framework::ToolDispatchError::RawWireLimit{tool_id,..}=>V::IntrinsicText(tool_id),_=>V::IntrinsicNull},[3]=>match source{semio_framework::ToolDispatchError::Factory{detail,..}=>V::IntrinsicText(detail),_=>V::IntrinsicNull},[4]=>match source{semio_framework::ToolDispatchError::RawWireLimit{actual,..}=>number(*actual),_=>V::IntrinsicNull},[5]=>match source{semio_framework::ToolDispatchError::RawWireLimit{maximum,..}=>number(*maximum),_=>V::IntrinsicNull},_=>return Err(invalid())})}
impl OriginalDomainProjection for OriginalConfigurationFailure{
 fn projection_identity(&self)->usize{self as*const Self as usize}
 fn projection_view(&self,path:&[usize])->Result<V<'_>,ValueError>{match self{Self::Original(source)=>project_original_turn_failure(source,path),Self::Admission(source)=>admission(source,path),Self::Native{producer,receiving}=>match path{[]=>Ok(V::IntrinsicObject(2)),[0,rest @ ..]=>project_original_value_error(producer,rest),[1,rest @ ..]=>project_original_turn_failure(receiving,rest),_=>Err(invalid())},Self::Store(source)=>match path{[]=>Ok(V::IntrinsicObject(2)),[0]=>Ok(V::IntrinsicText(store_kind(source))),[1,rest @ ..]=>store_value(source,rest),_=>Err(invalid())}}}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{match self{Self::Original(source)=>key_original_turn_failure(source,path,index),Self::Admission(_)=>match path{[]=>["kind","controllerId","toolId","detail","actual","maximum"].get(index).copied().ok_or_else(invalid),_=>Err(invalid())},Self::Native{producer,receiving}=>match path{[]=>["producer","receiving"].get(index).copied().ok_or_else(invalid),[0,rest @ ..]=>key_original_value_error(producer,rest,index),[1,rest @ ..]=>key_original_turn_failure(receiving,rest,index),_=>Err(invalid())},Self::Store(source)=>match path{[]=>["kind","value"].get(index).copied().ok_or_else(invalid),[1,rest @ ..]=>store_key(source,rest,index),_=>Err(invalid())}}}
}
